from pathlib import Path
import sys


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 match, found {count}")
    return text.replace(old, new, 1)


def main(path: str) -> None:
    p = Path(path)
    s = p.read_text(encoding="utf-8-sig")
    s = replace_once(s, 'APP_VERSION = "1.11.5"', 'APP_VERSION = "1.11.6"', 'version')

    s = replace_once(
        s,
        'from tkinter import filedialog, messagebox, ttk\n',
        'from tkinter import filedialog, messagebox, ttk, simpledialog\n',
        'simpledialog import',
    )

    marker = 'SETTINGS_TRANSFER_KEYS = ("contra_account", "vat_tax_type", "vat_rate", "fiscal_start_month", "project_code")\n\n\n'
    profile_code = '''SETTINGS_TRANSFER_KEYS = ("contra_account", "vat_tax_type", "vat_rate", "fiscal_start_month", "project_code")\n\n\nclass ProfileManager:\n    \"\"\"Manage company profiles with a completely separate SQLite database each.\n\n    The Default profile intentionally keeps using the historic DB_PATH so an\n    upgrade preserves all existing rules, settings and transaction history.\n    New profiles use their own database inside the app-data profiles folder.\n    \"\"\"\n    def __init__(self, root: Optional[Path] = None, legacy_db_path: Optional[Path] = None):\n        self.root = Path(root) if root is not None else app_data_dir()\n        self.root.mkdir(parents=True, exist_ok=True)\n        self.legacy_db_path = Path(legacy_db_path) if legacy_db_path is not None else DB_PATH\n        self.profile_dir = self.root / "profiles"\n        self.profile_dir.mkdir(parents=True, exist_ok=True)\n        self.index_path = self.root / "profiles.json"\n        self.data = self._load()\n\n    def _load(self) -> Dict[str, object]:\n        data: Dict[str, object] = {}\n        if self.index_path.exists():\n            try:\n                raw = json.loads(self.index_path.read_text(encoding="utf-8"))\n                if isinstance(raw, dict):\n                    data = raw\n            except Exception:\n                data = {}\n        profiles = data.get("profiles") if isinstance(data.get("profiles"), dict) else {}\n        profiles = {str(k): str(v) for k, v in profiles.items() if str(k).strip() and str(v).strip()}\n        if "default" not in profiles:\n            profiles["default"] = "Default"\n        active = str(data.get("active") or "default")\n        if active not in profiles:\n            active = "default"\n        clean = {"active": active, "profiles": profiles}\n        self.data = clean\n        self._save()\n        return clean\n\n    def _save(self) -> None:\n        self.index_path.write_text(json.dumps(self.data, indent=2, ensure_ascii=False), encoding="utf-8")\n\n    @property\n    def active_id(self) -> str:\n        return str(self.data.get("active") or "default")\n\n    def profiles(self) -> Dict[str, str]:\n        return dict(self.data.get("profiles") or {})\n\n    def names(self) -> List[str]:\n        return list(self.profiles().values())\n\n    def profile_name(self, profile_id: str) -> str:\n        return self.profiles().get(profile_id, profile_id)\n\n    def id_for_name(self, name: str) -> Optional[str]:\n        wanted = (name or "").strip()\n        for pid, pname in self.profiles().items():\n            if pname == wanted:\n                return pid\n        return None\n\n    def db_path(self, profile_id: str) -> Path:\n        if profile_id == "default":\n            return self.legacy_db_path\n        return self.profile_dir / f"{profile_id}.db"\n\n    def create_profile(self, name: str) -> str:\n        name = (name or "").strip()\n        if not name:\n            raise ValueError("Profile name is required.")\n        if any(existing.casefold() == name.casefold() for existing in self.names()):\n            raise ValueError("A profile with that name already exists.")\n        seed = f"{name}|{datetime.now().isoformat(timespec='microseconds')}"\n        pid = "profile_" + hashlib.sha1(seed.encode("utf-8")).hexdigest()[:12]\n        profiles = self.profiles()\n        profiles[pid] = name\n        self.data["profiles"] = profiles\n        self._save()\n        return pid\n\n    def rename_profile(self, profile_id: str, new_name: str) -> None:\n        new_name = (new_name or "").strip()\n        if not new_name:\n            raise ValueError("Profile name is required.")\n        profiles = self.profiles()\n        if profile_id not in profiles:\n            raise ValueError("Profile was not found.")\n        if any(pid != profile_id and pname.casefold() == new_name.casefold() for pid, pname in profiles.items()):\n            raise ValueError("A profile with that name already exists.")\n        profiles[profile_id] = new_name\n        self.data["profiles"] = profiles\n        self._save()\n\n    def set_active(self, profile_id: str) -> None:\n        if profile_id not in self.profiles():\n            raise ValueError("Profile was not found.")\n        self.data["active"] = profile_id\n        self._save()\n\n    def delete_profile(self, profile_id: str) -> None:\n        if profile_id == "default":\n            raise ValueError("The Default profile cannot be deleted because it contains the original app database.")\n        profiles = self.profiles()\n        if profile_id not in profiles:\n            raise ValueError("Profile was not found.")\n        db = self.db_path(profile_id)\n        profiles.pop(profile_id, None)\n        self.data["profiles"] = profiles\n        if self.active_id == profile_id:\n            self.data["active"] = "default"\n        self._save()\n        for candidate in (db, Path(str(db) + "-wal"), Path(str(db) + "-shm")):\n            try:\n                if candidate.exists():\n                    candidate.unlink()\n            except OSError:\n                pass\n\n\n'''
    s = replace_once(s, marker, profile_code, 'profile manager')

    s = replace_once(
        s,
        '''        self.minsize(1100, 680)\n        self.store = Store()\n        self.txns: List[Transaction] = []\n''',
        '''        self.minsize(1100, 680)\n        self.profile_manager = ProfileManager()\n        self.active_profile_id = self.profile_manager.active_id\n        self.store = Store(self.profile_manager.db_path(self.active_profile_id))\n        self.profile_var = tk.StringVar(value=self.profile_manager.profile_name(self.active_profile_id))\n        self.profile_db_var = tk.StringVar(value=f"Profile database: {self.store.path}")\n        self.txns: List[Transaction] = []\n''',
        'app profile init',
    )

    s = replace_once(
        s,
        '''        self._build()\n        self.protocol("WM_DELETE_WINDOW", self.on_close)\n\n    def _configure_style(self):\n''',
        '''        self._build()\n        self._refresh_profile_ui()\n        self.protocol("WM_DELETE_WINDOW", self.on_close)\n\n    def _refresh_profile_ui(self):\n        name = self.profile_manager.profile_name(self.active_profile_id)\n        self.profile_var.set(name)\n        if hasattr(self, "profile_combo"):\n            self.profile_combo.configure(values=self.profile_manager.names())\n        self.profile_db_var.set(f"Profile database: {self.store.path}")\n        self.title(f"{APP_NAME} {APP_VERSION} — {name}")\n\n    def _persist_profile_settings(self):\n        if not hasattr(self, "setting_vars"):\n            return\n        for key, var in self.setting_vars.items():\n            self.store.set_setting(key, var.get().strip())\n\n    def _load_active_profile_settings(self):\n        if not hasattr(self, "setting_vars"):\n            return\n        defaults = {"contra_account":"", "vat_tax_type":"", "vat_rate":"15", "fiscal_start_month":"3", "project_code":""}\n        for key, var in self.setting_vars.items():\n            var.set(self.store.get_setting(key, defaults.get(key, "")))\n\n    def _confirm_profile_change(self) -> bool:\n        if not (self.txns or self.receipts):\n            return True\n        return messagebox.askyesno(\n            APP_NAME,\n            "Switching company profiles will clear the currently loaded bank statement and any statement-only manual changes.\\n\\nSaved rules and settings are already stored in the current profile. Continue?"\n        )\n\n    def _clear_statement_for_profile_change(self):\n        self.txns = []\n        self.receipts = []\n        self.current_file = ""\n        self.parser_name = ""\n        for direction in self.DIRECTIONS:\n            self.search_vars[direction].set("")\n            self.filter_vars[direction].set("All")\n            self.repeat_vars[direction].set("— Select repeat description —")\n            self.repeat_display_to_key[direction] = {}\n            self.summary_vars[direction].set("No statement loaded")\n            tree = self.trees.get(direction)\n            if tree:\n                tree.delete(*tree.get_children())\n            rtree = self.recurring_trees.get(direction)\n            if rtree:\n                rtree.delete(*rtree.get_children())\n            self.update_repeat_dropdown(direction)\n        self.refresh_rules()\n\n    def _activate_profile(self, profile_id: str):\n        if profile_id == self.active_profile_id:\n            self._refresh_profile_ui()\n            return\n        self._persist_profile_settings()\n        try:\n            self.store.conn.close()\n        except Exception:\n            pass\n        self.profile_manager.set_active(profile_id)\n        self.active_profile_id = profile_id\n        self.store = Store(self.profile_manager.db_path(profile_id))\n        self._load_active_profile_settings()\n        self._clear_statement_for_profile_change()\n        self._refresh_profile_ui()\n        self.status_var.set(f"Switched to profile '{self.profile_manager.profile_name(profile_id)}'. Load that company's bank CSV to begin.")\n\n    def select_profile(self, event=None):\n        profile_id = self.profile_manager.id_for_name(self.profile_var.get())\n        if not profile_id or profile_id == self.active_profile_id:\n            self._refresh_profile_ui()\n            return\n        if not self._confirm_profile_change():\n            self._refresh_profile_ui()\n            return\n        self._activate_profile(profile_id)\n\n    def new_profile(self):\n        if not self._confirm_profile_change():\n            return\n        name = simpledialog.askstring(APP_NAME, "New company profile name:", parent=self)\n        if name is None:\n            return\n        try:\n            profile_id = self.profile_manager.create_profile(name)\n        except ValueError as e:\n            messagebox.showerror(APP_NAME, str(e), parent=self)\n            return\n        self._activate_profile(profile_id)\n\n    def rename_profile(self):\n        old_name = self.profile_manager.profile_name(self.active_profile_id)\n        name = simpledialog.askstring(APP_NAME, "Rename current company profile:", initialvalue=old_name, parent=self)\n        if name is None:\n            return\n        try:\n            self.profile_manager.rename_profile(self.active_profile_id, name)\n        except ValueError as e:\n            messagebox.showerror(APP_NAME, str(e), parent=self)\n            return\n        self._refresh_profile_ui()\n        self.status_var.set(f"Profile renamed to '{self.profile_manager.profile_name(self.active_profile_id)}'.")\n\n    def delete_profile(self):\n        if self.active_profile_id == "default":\n            messagebox.showinfo(APP_NAME, "The Default profile contains your original rules/settings database and cannot be deleted. You can rename it to the company name instead.")\n            return\n        name = self.profile_manager.profile_name(self.active_profile_id)\n        if not messagebox.askyesno(APP_NAME, f"Delete profile '{name}'?\\n\\nThis permanently deletes that profile's saved rules, settings and transaction history. This cannot be undone."):\n            return\n        self._persist_profile_settings()\n        try:\n            self.store.conn.close()\n        except Exception:\n            pass\n        old_id = self.active_profile_id\n        self.profile_manager.delete_profile(old_id)\n        self.active_profile_id = self.profile_manager.active_id\n        self.store = Store(self.profile_manager.db_path(self.active_profile_id))\n        self._load_active_profile_settings()\n        self._clear_statement_for_profile_change()\n        self._refresh_profile_ui()\n        self.status_var.set(f"Deleted profile '{name}'. Switched to '{self.profile_manager.profile_name(self.active_profile_id)}'.")\n\n    def _configure_style(self):\n''',
        'profile app methods',
    )

    s = replace_once(
        s,
        '''        ttk.Label(top, text=APP_NAME, font=("Segoe UI", 18, "bold")).pack(side="left")\n        ttk.Button(top, text="Load bank CSV…", command=self.load_csv, style="Accent.TButton").pack(side="left", padx=18)\n''',
        '''        ttk.Label(top, text=APP_NAME, font=("Segoe UI", 18, "bold")).pack(side="left")\n        profile_box = ttk.Frame(top)\n        profile_box.pack(side="left", padx=(18, 8))\n        ttk.Label(profile_box, text="Company profile:").pack(side="left", padx=(0,5))\n        self.profile_combo = ttk.Combobox(profile_box, textvariable=self.profile_var, values=self.profile_manager.names(), state="readonly", width=22)\n        self.profile_combo.pack(side="left")\n        self.profile_combo.bind("<<ComboboxSelected>>", self.select_profile)\n        ttk.Button(profile_box, text="New", command=self.new_profile).pack(side="left", padx=(5,2))\n        ttk.Button(profile_box, text="Rename", command=self.rename_profile).pack(side="left", padx=2)\n        ttk.Button(profile_box, text="Delete", command=self.delete_profile).pack(side="left", padx=2)\n        ttk.Button(top, text="Load bank CSV…", command=self.load_csv, style="Accent.TButton").pack(side="left", padx=8)\n''',
        'profile controls',
    )

    s = replace_once(
        s,
        '''        ttk.Label(bar, textvariable=self.status_var).pack(side="left")\n        ttk.Label(bar, text=f"Rules/settings saved in {DB_PATH}", foreground="#666666").pack(side="right")\n''',
        '''        ttk.Label(bar, textvariable=self.status_var).pack(side="left")\n        ttk.Label(bar, textvariable=self.profile_db_var, foreground="#666666").pack(side="right")\n''',
        'profile database status',
    )

    s = replace_once(
        s,
        '''        transfer_note = ("Upgrading from v1.10 to v1.11 on the same Windows PC keeps these settings automatically because both versions use the same settings database. "\n                         "For another PC, Import Settings can read either a v1.11 JSON settings backup or a copied v1.10 pastel_payment_assistant.db file.")\n''',
        '''        transfer_note = ("The Default company profile uses the original Pastel Payment Assistant database, so existing rules/settings/history are preserved when upgrading. "\n                         "Each additional company profile has its own separate database. Settings import/export acts only on the currently selected profile.")\n''',
        'settings profile note',
    )

    s = replace_once(
        s,
        '''            f.write(f"{APP_NAME} {APP_VERSION}\\nPre-import validation report\\nGenerated: {datetime.now():%Y-%m-%d %H:%M:%S}\\nSource: {self.current_file}\\n\\n")\n''',
        '''            f.write(f"{APP_NAME} {APP_VERSION}\\nPre-import validation report\\nProfile: {self.profile_manager.profile_name(self.active_profile_id)}\\nGenerated: {datetime.now():%Y-%m-%d %H:%M:%S}\\nSource: {self.current_file}\\n\\n")\n''',
        'validation report profile name',
    )

    s = replace_once(
        s,
        '''    def on_close(self):\n        try:\n            self.save_settings(quiet=True)\n        except Exception:\n            pass\n        self.destroy()\n''',
        '''    def on_close(self):\n        try:\n            self._persist_profile_settings()\n            self.store.conn.close()\n        except Exception:\n            pass\n        self.destroy()\n''',
        'profile close persistence',
    )

    test_marker = '    # Receipt and payment rules with the same description must never cross-apply.\n'
    tests = '''    # v1.11.6: company profiles keep rules/settings/history in separate databases.\n    import tempfile\n    with tempfile.TemporaryDirectory() as profile_td:\n        profile_root = Path(profile_td)\n        legacy_db = profile_root / "pastel_payment_assistant.db"\n        pm = ProfileManager(profile_root, legacy_db)\n        assert pm.active_id == "default"\n        assert pm.db_path("default") == legacy_db\n        company_b = pm.create_profile("Company B")\n        assert pm.db_path(company_b) != pm.db_path("default")\n        default_store = Store(pm.db_path("default"))\n        company_store = Store(pm.db_path(company_b))\n        default_store.set_setting("contra_account", "1100000")\n        company_store.set_setting("contra_account", "1200000")\n        default_store.save_rule(Rule(None, "DEFAULT ONLY", "SMART", "DEFAULT ONLY 1234", "7100001", False, 0, direction="PAYMENT"))\n        company_store.save_rule(Rule(None, "COMPANY B ONLY", "SMART", "COMPANY B 5678", "7200001", False, 0, direction="PAYMENT"))\n        assert default_store.get_setting("contra_account") == "1100000"\n        assert company_store.get_setting("contra_account") == "1200000"\n        assert [r.name for r in default_store.all_rules()] == ["DEFAULT ONLY"]\n        assert [r.name for r in company_store.all_rules()] == ["COMPANY B ONLY"]\n        default_store.conn.close(); company_store.conn.close()\n        pm.set_active(company_b)\n        pm_again = ProfileManager(profile_root, legacy_db)\n        assert pm_again.active_id == company_b\n        pm_again.rename_profile(company_b, "Second Company")\n        assert pm_again.profile_name(company_b) == "Second Company"\n        pm_again.delete_profile(company_b)\n        assert pm_again.active_id == "default" and pm_again.id_for_name("Second Company") is None\n\n'''
    s = replace_once(s, test_marker, tests + test_marker, 'profile isolation self tests')

    p.write_text(s, encoding='utf-8')
    print(f'Transformed {p} to v1.11.6 with isolated company profiles')


if __name__ == '__main__':
    main(sys.argv[1])
